    int shortestWay(string source, string target) {
        vector<bool> has_char(26, false);
        for (char c : source) has_char[c - 'a'] = true;
        for (char c : target) {
            if (!has_char[c - 'a']) return -1;
        }

        int res = 0, j = 0;
        int n = target.size(), m = source.size();
