class Solution {
    public int shortestWay(String source, String target) {
        boolean[] hasChar = new boolean[26];
        for (int i = 0; i < source.length(); ++i) hasChar[source.charAt(i) - 'a'] = true;
        for (int i = 0; i < target.length(); ++i) {
            if (!hasChar[target.charAt(i) - 'a']) return -1;
        }

        int res = 0, j = 0;
        int n = target.length(), m = source.length();
        while (j < n) {
            int i = 0;
            while (i < m && j < n) {
                if (source.charAt(i) == target.charAt(j)) j++;
                i++;
            }
            res++;
        }
        return res;
    }
}

var shortestWay = function(source, target) {
    const sourceChars = new Set(source);
    for (const c of target) {
        if (!sourceChars.has(c)) return -1;
    }

    let res = 0, j = 0;
    const n = target.length, m = source.length;
    while (j < n) {
        let i = 0;
        while (i < m && j < n) {
            if (source[i] === target[j]) j++;
            i++;
        }
        res++;
    }
    return res;
};
